**Optimistic Lock:**

```javascript
// optimistic-lock.js
const mongoose = require('mongoose');

module.exports = function (schema) {
  schema.methods.updateOne = async function (query, options) {
    const versionField = '_version';
    let document = this;

    // Fetch the document from the database with the latest version field
    const matchingDocument = await this.constructor.findOne(query).sort({ [versionField]: -1 }).select([versionField]);

    if (matchingDocument && document._id.toString() !== matchingDocument._id.toString()) {
      // If another client has updated the document, it will have a higher version number
      throw new Error('Optimistic lock conflict occurred.');
    }

    // If no matching document was found, the current document is assumed to be the most recent one

    // Update the document and increment the version field
    document = await this.constructor.findOneAndUpdate(query, { $set: { [versionField]: (document[versionField] || 0) + 1 }, $set: options.setFields }, options);

    return document;
  };
};
```

