  try {
    const filePath = req.params.filePath;
    const logs = await Log.find({ path: filePath }).exec();
    if (!logs || !logs.length) return res.status(404).send('No logs found for this file path');

    // Check cache for existing processed results and return it if available
    const cachedResult = await redisClient.get(filePath);
    if (cachedResult) return res.send(JSON.parse(cachedResult));

    res.send(logs);
  } catch (err) {
    console.error(err);
    res.status(500).send(err);
  }
});

// API endpoint to trigger an external logging call
app.post('/logToAPI', async (req, res) => {
  const { filePath, apiUrl } = req.body;
  try {
    const response = await axios.post(apiUrl, { filePath });
    res.send(response.data);
  } catch (err) {
