    public class SecureDataProcessor
    {
        private readonly HttpClient _httpClient;
        private static readonly ConcurrentDictionary<string, byte[]> _decryptionTasks = new();
        private static readonly ILogger _logger = LogManager.GetCurrentClassLogger();

        public SecureDataProcessor()
        {
            _httpClient = new HttpClient();
        }

        public async Task ProcessEncryptedDataAsync(string url, byte[] encryptionKey, byte[] iv)
        {
            try
            {
                var response = await _httpClient.GetAsync(url);

                if (!response.IsSuccessStatusCode)
                {
                    HandleError($"Failed to fetch data from URL '{url}'");
                    return;
                }

                var decryptionTaskKey = Guid.NewGuid().ToString();
                _decryptionTasks[decryptionTaskKey] = await response.Content.ReadAsByteArrayAsync();

                // Fetch the stored decrypted data when it's ready
                Task.Run(async () =>
                {
                    while (!_decryptionTasks.TryRemove(decryptionTaskKey, out var decryptedData))
                        await Task.Delay(100);

                    if (decryptedData is null)
                        return;

                    DecryptAndDeserializeData(decryptedData, encryptionKey, iv);
                });
            }
            catch (Exception ex)
            {
                HandleError($"An error occurred while processing encrypted data: {ex.Message}");
            }
        }

        private void DecryptAndDeserializeData(byte[] encryptedData, byte[] encryptionKey, byte[] iv)
        {
            try
            {
                using (var aes = AES.Create())
                {
                    aes.Key = encryptionKey;
                    aes.IV = iv;

                    var decryptedData = Decrypt(aes, encryptedData);

                    using (var memoryStream = new MemoryStream(decryptedData))
                    using (var binaryFormatter = new BinaryFormatter())
                    {
                        var dataModel = (CustomDataModel)binaryFormatter.Deserialize(memoryStream);
                        // Process the deserialized data model as needed...
                    }
                }
            }
            catch (Exception ex)
            {
                HandleError($"An error occurred while decrypting and deserializing data: {ex.Message}");
            }
        }

        private static byte[] Decrypt(Aes aes, byte[] encryptedData)
        {
            using (var memoryStream = new MemoryStream(encryptedData))
            using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Read))
                return cryptoStream.ToArray();
        }

        private static void HandleError(string errorMessage)
        {
            _logger.Error(errorMessage);
        }
    }

