['```java
package com.example.serialization;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.Constructor;
import java.net.URLClassLoader;
import java.util.ConcurrentHashMap;
import java.util.LinkedList;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Level;
import java.util.logging.Logger;

public final class SerializationUtility {
    private static final Logger LOGGER = Logger.getLogger(SerializationUtility.class.getName());
    private static final ConcurrentHashMap<byte[], Object> CACHE = new ConcurrentHashMap<>();
    private static final AtomicLong CACHE_HIT_COUNT = new AtomicLong();
    private static final AtomicLong CACHE_MISS_COUNT = new AtomicLong();
    private static final LinkedList<Class<?>> LOADED_CLASSES = new LinkedList<>();
    private static URLClassLoader classLoader;

    public static <T> T deserialize(byte[] bytes, Class<T> targetClass) {
        if (targetClass == null || bytes == null) {
            throw new IllegalArgumentException("Target class and byte array must not be null.");
        }

        Object cachedObject = CACHE.get(bytes);
        if (cachedObject != null) {
            CACHE_HIT_COUNT.incrementAndGet();
            return (T) cachedObject;
        }
        CACHE_MISS_COUNT.incrementAndGet();

        synchronized (CACHE) {
            if (CACHE.get(bytes) == null) {
                try {
                    Class<?> clazz = LOADED_CLASSES.stream()
                            .filter(c -> c.isAssignableFrom(targetClass))
                            .findFirst()
                            .orElseGet(() -> loadClassIfAvailable(targetClass));

                    ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
                    ObjectInputStream ois = new ObjectInputStream(bis);
                    Object object = ois.readObject();
                    ois.close();

                    Constructor<?> constructor = clazz.getDeclaredConstructor();
                    constructor.setAccessible(true);
                    Object result = constructor.newInstance((object instanceof Object[]) ? object : new Object[]{object});
                    CACHE.putIfAbsent(bytes, result);

                    return (T) result;
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Failed to deserialize byte array.", e);
                    throw new SerializationException("Error occurred while deserializing byte array.", e);
                }
            }
        }
    }

    private static Class<?> loadClassIfAvailable(Class<?> targetClass) {
        if (classLoader == null) {
            classLoader = new URLClassLoader(new URL[0]);
        }

        try {
            Class<?> loadedClass = classLoader.loadClass(targetClass.getName());
            LOADED_CLASSES.add(loadedClass);
            return loadedClass;
        } catch (ClassNotFoundException e) {
            LOGGER.log(Level.INFO, "Class not found in the classpath: {0}", targetClass.getName());
            return null;
        }
    }
}

public final class SerializationException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public SerializationException(String message) {
        super(message);
    }

    public SerializationException(String message, Throwable cause) {
        super(message, cause);
    }
}
```
