```javascript
const Uploader = (options) => {
  // Implement constructor logic, validate input, set default options, etc.

  const {
    url,
    maxFileSize,
    fileTypeRegex,
    authService,
    logService,
    retryPolicy,
    resumableUploads,
    minBackoffMs,
    maxBackoffMs,
    maxAttempts,
    cloudService,
    http2Enabled,
    asyncRequests,
    // Additional options...
  } = options;

  let currentAttempt = 0;
  let currentChunkIndex = 0;
  let totalUploadedBytes = 0;
  let totalFileSizeBytes = 0;
  let isChunkInProgress = false;

  async function upload(file) {
    // Validate file type and size, ensure access permissions, etc.

    totalFileSizeBytes = file.size;

    if (totalFileSizeBytes > maxFileSize) {
      throw new Error("File exceeds the maximum allowed size.");
    }

    if (!fileTypeRegex.test(file.type)) {
      throw new Error("Invalid file type.");
    }

    // Initiate upload process using cloudService and external dependencies.

    const chunks = chunkFile(file);

    for (const chunk of chunks) {
      if (!isChunkInProgress) {
        isChunkInProgress = true;
        currentAttempt = 0;

        // Attempt uploading the current chunk.
        uploadChunk(chunk).catch((error) => handleError(error));
      }
    }
  }

  async function uploadChunk(chunk) {
    try {
      const response = await cloudService.upload(url, chunk);

      if (response.ok) {
        totalUploadedBytes += chunk.size;
        logSuccess(response);

        if (!resumableUploads || currentChunkIndex === chunks.length - 1) {
          isChunkInProgress = false;
          return;
        }

        currentChunkIndex++;
        uploadChunk(chunks[currentChunkIndex]);
      } else {
        throw new Error("Failed to upload chunk.");
      }
    } catch (error) {
      handleError(error);
    } finally {
      isChunkInProgress = false;
    }
  }

  function handleError(error) {
    if (currentAttempt < maxAttempts) {
      logError(error);

      currentAttempt++;

      if (retryPolicy && currentAttempt <= maxAttempts) {
        setTimeout(() => uploadChunk(chunks[currentChunkIndex]), getBackoffMs());
      } else {
        throw error;
      }
    } else {
      logError(error);
      throw error;
    }
  }

  function logSuccess(response) {
    logService.log(`Upload success: ${response.statusText}`);
  }

  function logError(error) {
    logService.log(`Upload error: ${error.message}`);
  }

  // Additional functions for managing retry policies, progress tracking, etc.
}
