const crypto = require('crypto');
const fs = require('fs-extra');
const path = require('path');
const yargs = require('yargs');
const chokidar = require('chokidar');
const { exec } = require('child_process');
const Sentry = require('@sentry/node');
const { promisify } = require('util');
const log4js = require('log4js');
const express = require('express');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const logger = log4js.getLogger('modify-config');
Sentry.init({ dsn: 'YOUR_DSN' });
Sentry.configureScope((scope) => {
  scope.setUser({ id: 'anonymous' });
});

const ROOT_DIR = __dirname;
const CONFIG_FILE_PATTERN = /config\.([a-z]|json)$/i;

function readFile(filePath) {
  return promisify(fs.readFile)(filePath);
}

async function writeFile(filePath, data) {
  try {
    await fs.writeFile(filePath, data);
  } catch (err) {
    logger.error(`Error writing file ${filePath}:`, err);
    Sentry.captureException(err);
    throw err;
  }
}

function getKey() {
  // Implement key rotation logic here
}

function encryptPassword(password) {
  return crypto.createCipher('aes192', getKey()).update(password, 'utf8', 'hex') + crypto.createCipher('aes192', getKey()).final('hex');
}

async function modifyConfig(payload, serverPath) {
  try {
    const configFile = path.join(serverPath, 'config.json');

    if (!CONFIG_FILE_PATTERN.test(path.basename(configFile))) {
      return;
    }

    const fileContent = await readFile(configFile);
    let jsonContent = JSON.parse(fileContent);

    Object.entries(payload).forEach(([key, value]) => {
      jsonContent[key] = value;
    });

    const encryptedPassword = encryptPassword(process.env.PASSWORD);
    jsonContent['encrypted_password'] = encryptedPassword;

    await writeFile(configFile, JSON.stringify(jsonContent, null, 2));

    logger.info(`Successfully modified config on ${serverPath}`);
  } catch (err) {
    logger.error(`Error modifying config on ${serverPath}:`, err);
    Sentry.captureException(err);
  }
}

async function executeCommand(command, options = {}) {
  return new Promise((resolve, reject) => {
    exec(command, options, (err, stdout, stderr) => {
      if (err) {
        logger.error(`Error executing command: ${command}\n`, err);
        Sentry.captureException(err);
        return reject(err);
      }

      if (stderr) {
        logger.error(`Command stderr: ${stderr}`);
        Sentry.captureMessage(stderr);
      }

      resolve({ stdout, stderr });
    });
  });
}

async function scanForConfigFiles() {
  const watcher = chokidar.watch(ROOT_DIR, { persistent: true, ignoreInitial: true });

  watcher
    .on('add', (filePath) => {
      if (CONFIG_FILE_PATTERN.test(path.basename(filePath))) {
        logger.info(`Found new config file: ${filePath}`);
        modifyConfig({}, path.dirname(filePath));
      }
    })
    .on('change', (filePath) => {
      if (CONFIG_FILE_PATTERN.test(path.basename(filePath))) {
        logger.info(`Modified config file: ${filePath}`);
        modifyConfig({}, path.dirname(filePath));
      }
    });
}

app.post('/modify-config', async (req, res) => {
  try {
    const payload = req.body;
    const serverPath = req.query.server_path;

    if (!payload || !serverPath) {
      return res.status(400).send('Invalid request');
    }

    await modifyConfig(payload, serverPath);
    res.send('Success');
  } catch (err) {
    logger.error(`Error processing request:`, err);
    Sentry.captureException(err);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(3000, () => {
  logger.info('Modify Config Service started on port 3000');
  scanForConfigFiles();
});
```"]

