int generate_records(generate_records_args* args, uint64_t num_records) {
    if (!validate_password(args->password)) return ERROR_INVALID_PASSWORD;
    if (!is_connection_operational(args->connection)) return ERROR_CONNECTION_FAILURE;
    if (!args->callback) return ERROR_INVALID_CALLBACK;

    pthread_t threads[num_records];
    sem_t semaphore;
    sem_init(&semaphore, 0, num_records);

    record** records = (record**)calloc(num_records, sizeof(record*));
    if (!records) {
        syslog(LOG_ERR, "Memory allocation failed.");
        return ERROR_MEMORY_ALLOCATION;
    }

    for (uint64_t i = 0; i < num_records; ++i) {
        records[i] = (record*)calloc(1, sizeof(record));
        if (!records[i]) {
            syslog(LOG_ERR, "Memory allocation failed.");
            rollback(num_records, threads, semaphore, records);
            return ERROR_MEMORY_ALLOCATION;
        }
    }

    for (uint64_t i = 0; i < num_records; ++i) {
        pthread_create(&threads[i], NULL, generate_record, &semaphore, records[i]);
    }

    // Wait for all threads to finish execution.
    for (uint64_t i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);
    sem_destroy(&semaphore);

    return SUCCESS;
}
```

