// Custom allocator and memory pool for efficient memory management
struct MemChunk {
    void *start;
    size_t size;
};

// Custom Allocator Function
void *custom_malloc(size_t size) {
    static struct MemChunk chunk = {0, 0};
    if (chunk.size <= size) {
        char* temp = (char *) mmap(NULL, size + sizeof(struct MemChunk), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (temp == MAP_FAILED) {
            return NULL;
        }
        struct MemChunk *mem = (struct MemChunk *) temp;
        mem->size = size;
        chunk.start = (char *) ((size_t) mem + sizeof(struct MemChunk));
        chunk.size += size;
    }
    return (void*)((char *)&chunk - sizeof(struct MemChunk) + chunk.start);
}

