[' Due to the complexity of this task, I will break it down into smaller manageable parts for both C and Java components.

C Component: logConditionMessage

```c
#include <iostream>
#include <fstream>
#include <sstream>
#include <map>
#include <vector>
#include <mutex>

enum LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

class Sink {
public:
    virtual void log(const std::string& message) = 0;
};

class ConsoleSink : public Sink {
public:
    void log(const std::string& message) override {
        std::cout << message << std::endl;
    }
};

class FileSink : public Sink {
private:
    std::ofstream file;
public:
    explicit FileSink(const std::string& filename) : file(filename, std::ios_base::app) {}
    void log(const std::string& message) override {
        file << message << std::endl;
    }
};

class Logger {
private:
    LogLevel level;
    std::map<LogLevel, std::vector<Sink*>> sinks;
    std::mutex mutex;
public:
    Logger(LogLevel initial_level) : level(initial_level) {}

    void addSink(LogLevel level, Sink* sink) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sinks.find(level) == sinks.end()) {
            sinks[level] = {};
        }
        sinks[level].push_back(sink);
    }

    void logConditionMessage(const std::string& condition, const std::string& message) {
        if (getLevel() >= LogLevel(std::stoi(condition)) && level < FATAL) {
            std::lock_guard<std::mutex> lock(mutex);
            for (auto& sink : sinks[getLevel()]) {
                sink->log(message);
            }
        }
    }

    LogLevel getLevel() const { return level; }
    void setLevel(LogLevel new_level) { level = new_level; }
};
```

