[' Here is the C++ code for the `runAndLogTest` function:

```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <cstdarg>
#include <mutex>
#include <atomic>
#include <thread>

// Define the log severity levels and custom message formatting.
enum class LogLevel { Debug, Info, Warning, Error, Critical };

class Logger {
public:
    virtual void log(LogLevel level, const char* format, ...) = 0;
};

class ThreadSafeLogger : public Logger {
private:
    std::mutex mtx;
    Logger* delegate;
public:
    explicit ThreadSafeLogger(Logger* dlg) : delegate(dlg) {}
    void log(LogLevel level, const char* format, ...) override {
        std::lock_guard<std::mutex> lock(mtx);
        va_list args;
        va_start(args, format);
        delegate->log(level, format, args);
        va_end(args);
    }
};

// The runAndLogTest function implementation.
void runAndLogTest(std::forward_list<std::string>* list, const std::string& testLabel,
                   const std::string& targetElement, bool shouldLog, Logger& logger) {
    auto it = list->begin();
    if (it == list->end() || *it != targetElement) {
        it = list->insert_after(++it, testLabel); // Insert at the end if not found.
    } else {
        ++it; // Advance past the target element.
        it = list->insert_after(it, testLabel); // Insert after the target element.
    }

    if (shouldLog) {
        logger.log(LogLevel::Info, "Inserted label: %s at position %zu", testLabel.c_str(), std::distance(list->begin(), it));
    }
}

// A simple logging service implementation for demonstration purposes.
class SimpleLogger : public Logger {
public:
    void log(LogLevel level, const char* format, ...) override {
        va_list args;
        std::vector<char> buffer(128);
        va_start(args, format);
        vsnprintf(buffer.data(), buffer.size(), format, args);
        va_end(args);
        // Here you can integrate with the actual logging service.
        std::cout << "[" << level << "] " << buffer.data() << '\n';
    }
};

