    public class ContentController : ControllerBase
    {
        private readonly IContentService _contentService;
        private readonly ILogger<ContentController> _logger;

        public ContentController(IContentService contentService, ILogger<ContentController> logger)
        {
            _contentService = contentService;
            _logger = logger;
        }

        [HttpPost]
        public async Task<ActionResult<ContentResponse>> Create([FromQuery] string identifier, [FromBody] ContentRequest request)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            try
            {
                var content = await _contentService.CreateAsync(identifier, request);
                await _contentService.SaveChangesAsync();

                // Trigger client-side event or redirect
                if (HttpContext.Response.OnStarting(() => HttpContext.Response.StatusCode == 200))
                {
                    HttpContext.Response.Headers.Add("Refresh", "5;url=/" + identifier);
                }

                return Ok(new ContentResponse { Id = content.Id, Data = content.Data });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error creating content");
                return StatusCode((int)HttpStatusCode.InternalServerError);
            }
        }

        [HttpPut]
        public async Task<ActionResult<ContentResponse>> Update([FromQuery] string identifier, [FromBody] ContentRequest request)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            try
            {
                var content = await _contentService.GetAsync(identifier);
                if (content == null)
                {
                    return NotFound();
                }

                if (!content.Version.Equals(request.Version))
                {
                    return Conflict();
                }

                content.Data = request.Data;
                content.Version++;
                await _contentService.SaveChangesAsync();

                return Ok(new ContentResponse { Id = content.Id, Data = content.Data });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating content");
                return StatusCode((int)HttpStatusCode.InternalServerError);
            }
        }

        [HttpDelete]
        public async Task<ActionResult> Delete([FromQuery] string identifier)
        {
            try
            {
                var content = await _contentService.GetAsync(identifier);
                if (content == null)
                {
                    return NotFound();
                }

                content.Data = new ContentData(); // Default values
                await _contentService.SaveChangesAsync();

                return Ok();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error deleting content");
                return StatusCode((int)HttpStatusCode.InternalServerError);
            }
        }
    }

