```javascript
// cache.js
class Cache {
  constructor() {
    this.store = new Map();
  }

  getOrFetch(key, fetchFn) {
    const cachedValue = this.get(key);
    if (cachedValue) return Promise.resolve(cachedValue);

    return fetchFn().then(data => {
      this.set(key, data);
      return data;
    });
  }

  get(key) {
    return this.store.get(key);
  }

  set(key, value) {
    if (this.evictStaleData()) {
      console.log('Evicted stale data from cache');
    }

    this.store.set(key, value);
  }

  evictStaleData() {
    // Implement dynamic cache eviction policies based on the freshness of data retrieved from each API
    return false;
  }
}

module.exports = Cache;
