// Create a class for DynamicResourceProcessor
class DynamicResourceProcessor {
    private api: AxiosInstance;
    private cache: WeakMap<ResourceBundle, ValidationResult>;

    constructor() {
        this.api = axios.create({
            // Configure your axios instance with baseURL, timeout, headers etc...
        });
        this.cache = new WeakMap();
    }

    // Function to validate a resource bundle and handle concurrency
    async validateBundle(bundle: ResourceBundle): Promise<ValidationResult> {
        let result = this.cache.get(bundle);

        if (result) {
            return result;
        }

        const promises = bundle.files.map((file) => this.validateFile(file));
        const validationResults = await q.all(promises);
        const allValid = lodash.every(validationResults, (r) => r.isValid);

        if (!allValid) {
            result = {
                bundleId: bundle.id,
                isValid: false,
                validationErrors: lodash.flatMap(validationResults, (v) => v.validationErrors),
            };
            this.cache.set(bundle, result);
        } else {
            result = {
                bundleId: bundle.id,
                isValid: true,
            };
            this.cache.set(bundle, result);
        }

        return result;
    }

    // Function to validate a single file and handle retries if needed
