import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;

public class CommandExecutor {
    public void executeCommand(String command, String workingDirectory) throws IOException {
        Path fileToDelete = Path.of(workingDirectory, "tempFile");
        if (Files.exists(fileToDelete)) {
            Files.deleteIfExists(fileToDelete);
        }
        Process process = Runtime.getRuntime().exec(command, null, new File(workingDirectory));

        BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = input.readLine()) != null) {
            System.out.println(line);
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new RuntimeException("Command execution failed with exit code: " + exitCode);
        }
    }
}
