[' ```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json;
using RestSharp;

namespace SecureEncryptionService
{
    public class SecureEncryptionService
    {
        private readonly Aes _aes;
        private readonly HMACSHA256 _hmac;
        private readonly string _loggingApiUrl;

        public SecureEncryptionService(string key, byte[] iv, string loggingApiUrl)
        {
            ValidateKeyAndIVLengths(key, iv);
            _aes = AES.Create();
            _hmac = new HMACSHA256(key);
            _loggingApiUrl = loggingApiUrl;
            _aes.Key = key;
            _aes.IV = iv;
        }

        private void ValidateKeyAndIVLengths(string key, byte[] iv)
        {
            if (key.Length != 16 && key.Length != 24 && key.Length != 32)
                throw new ArgumentException("Invalid AES key length.");

            if (iv.Length != 16)
                throw new ArgumentException("Invalid IV length.");
        }

        public byte[] Encrypt(byte[] message, string hmacKey = null)
        {
            var encryptedData = _aes.CreateEncryptor().TransformFinalBlock(message, 0, message.Length);
            var encryptedWithPadding = PKCS7Padding.Pad(encryptedData);

            if (hmacKey != null)
                _hmac.ComputeHash(encryptedWithPadding);

            return encryptedWithPadding;
        }

        public byte[] Decrypt(byte[] encryptedData, string hmacKey = null)
        {
            var decryptedData = PKCS7Padding.Unpad(encryptedData);
            var decrypted = _aes.CreateDecryptor().TransformFinalBlock(decryptedData, 0, decryptedData.Length);

            if (hmacKey != null)
            {
                var expectedHmac = _hmac.ComputeHash(encryptedData);
                if (!AreArraysEqual(expectedHmac, Array.Empty<byte>()))
                    throw new Exception("Invalid HMAC.");
            }

            return decrypted;
        }

        private bool AreArraysEqual(byte[] a, byte[] b)
        {
            if (ReferenceEquals(a, b)) return true;
            if (ReferenceEquals(a, null) || ReferenceEquals(b, null)) return false;
            if (a.Length != b.Length) return false;

            for (int i = 0; i < a.Length; ++i)
                if (a[i] != b[i])
                    return false;

            return true;
        }

        public void LogDecryptionFailure(string errorMessage)
        {
            var request = new RestRequest($"{_loggingApiUrl}/logs", Method.POST);
            request.AddJsonBody(new { timestamp = DateTime.Now, message = errorMessage });
            var client = new RestClient();
            client.ExecuteAsync(request);
        }
    }

    public static class PKCS7Padding
    {
        public static byte[] Pad(byte[] buffer) => Pad(buffer, (int)AesManaged.KeySize / 8);

        public static byte[] Unpad(byte[] buffer) => Unpad(buffer, (int)AesManaged.KeySize / 8);

        private const string PaddingCharacter = (char)0x05;

        private static void PadBuffer(Span<byte> buffer, int blockSize)
        {
            var numBytesToPad = blockSize - (buffer.Length % blockSize);
            Buffer.BlockCopy(new byte[] { PaddingCharacter }, 0, buffer.Slice(buffer.Length - numBytesToPad), numBytesToPad);
        }

        private static int GetPaddingLength(byte[] buffer, int blockSize) => buffer[buffer.Length - 1];

        public static byte[] Pad(byte[] buffer, int blockSize)
        {
            var paddingLength = GetPaddingLength(buffer, blockSize);
            if (paddingLength == blockSize)
                return buffer;

            var newBuffer = new byte[buffer.Length + paddingLength];
            Buffer.BlockCopy(buffer, 0, newBuffer, 0, buffer.Length);
            PadBuffer(newBuffer.AsSpan(buffer.Length), blockSize);

            return newBuffer;
        }

        public static byte[] Unpad(byte[] buffer, int blockSize)
        {
            var paddingLength = GetPaddingLength(buffer, blockSize);
            if (paddingLength == 0)
                throw new Exception("Invalid PKCS7 padding.");

            return buffer[..^paddingLength];
        }
    }
}
```
This code implements a `SecureEncryptionService` that provides AES-CBC encryption and decryption with optional HMAC for message integrity verification. The service can be easily extended to support multiple padding modes by modifying the `PKCS7Padding` class. It includes methods to validate key and IV lengths, handles errors gracefully, logs relevant events to an external API, and is designed to be scalable and maintainable. Unit tests should be implemented to cover various scenarios, including edge cases and potential error conditions.']

