void process_file(FILE *fp, void (*func)(char *line)) {
    pthread_t thread_id;
    size_t read_size = 4096;
    char *buffer = malloc(read_size);

    for (ssize_t i = 0; i < file_stat.st_size; i += read_size) {
        ssize_t bytes_read = fread(buffer, 1, read_size, fp);
        if (bytes_read == 0) break;

        pthread_create(&thread_id, NULL, func, buffer);
        pthread_join(thread_id, NULL);
    }

    free(buffer);
}
