```cpp
#include <unordered_map>
#include <memory>

class Cache {
public:
    std::unordered_map<int, std::shared_ptr<Resource>> cache;
    double ttl = 60; // Time-to-live in seconds

    std::shared_ptr<Resource> get(const int id) {
        if (cache.count(id)) {
            auto expiration = std::chrono::system_clock::now() + std::chrono::seconds(ttl);
            if (expiration > cache[id]->second_expire)
                return cache[id];
        }
        // Load from API or local storage if not in cache...
    }

    void put(const int id, const std::shared_ptr<Resource>& resource) {
        resource->second_expire = std::chrono::system_clock::now() + std::chrono::seconds(ttl);
        cache[id] = resource;
    }
};
