```cpp
extern "C" __declspec(dllexport) std::string md5Hash(const std::string& input) {
    using namespace System;
    using namespace System.Security.Cryptography;

    String^ str = gcnew String(input.begin(), input.end());
    MD5Managed^ hashAlgorithm = gcnew MD5Managed();
    Byte[] byteArray = Encoding::UTF8->GetBytes(str);
    Byte[ ] hashedData = hashAlgorithm->ComputeHash(byteArray);

    StringBuilder sb = gcnew StringBuilder();
    for (Byte b : hashedData) {
        sb->AppendFormat("{0:x2}", b);
    }
    return gcnew String(sb->ToString());
