#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

void modify_filename(char *input_filename) {
    int extension_start = -1, num_digits = 4, file_type[3] = {"txt", "json", "xml"};

    for (int i = strlen(input_filename)-1; i >= 0; --i) {
        if (isalnum(input_filename[i])) extension_start = i;
        if (extension_start != -1 && input_filename[i] == '.') break;
    }

    char *new_filename = malloc((strlen(input_filename)-extension_start) + num_digits + strlen(file_type[0])+1);
    strncat(new_filename, input_filename, extension_start);
    sprintf(new_filename+(strlen(input_filename)-extension_start), "%0*d%s", num_digits, rand() % 10000, file_type[0]);

    if (strlen(file_type) < 3) {
        for (int i = 1; i < 3; ++i) strcat(new_filename, file_type[i]);
    }

    free(input_filename);
    input_filename = new_filename;
}
```']

