#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <json-c/json.h>
#include <curl/curl.h>

typedef struct {
    char *key;
    char *value;
} Metadata;

typedef struct {
    char filepath[256];
    size_t num_items;
    Metadata **metadata;
    pthread_mutex_t mutex;
    CURL *remote_api;
    size_t concurrent_requests;
} ResourceBundle;

static size_t write_data(void *ptr, size_t size, size_t nmemb, void *stream) {
    char *buf = malloc(size * nmemb);
    memcpy(buf, ptr, size * nmemb);

    json_object *json_obj;
    json_object *item;
    cJSON *root;
    cJSON *data;
    Metadata *metadata;

    json_object_from_string(buf, buf + size * nmemb, 0, &json_obj);
    root = json_object_get_child(json_obj, "root");
    data = json_object_get_child(root, "data");

    for (int i = 0; i < json_array_get_length(data); ++i) {
        item = json_array_get_index(data, i);
        metadata = malloc(sizeof(Metadata));

        metadata->key = strdup(json_object_get_name(item));
        metadata->value = json_object_get_string(item);
    }

    ResourceBundle *rb = (ResourceBundle *)stream;
    size_t new_num_items = rb->num_items + json_array_get_length(data);

    Metadata **new_metadata = realloc(rb->metadata, sizeof(Metadata) * new_num_items);
    memset(new_metadata + rb->num_items, 0, (new_num_items - rb->num_items) * sizeof(Metadata));

    memcpy(new_metadata + rb->num_items, metadata, sizeof(Metadata) * json_array_get_length(data));
    free(buf);

    pthread_mutex_lock(&rb->mutex);
    rb->num_items = new_num_items;
    rb->metadata = new_metadata;
    pthread_mutex_unlock(&rb->mutex);

    return size * nmemb;
}

static int file_exists(const char *filepath) {
    struct stat st;
    return (stat(filepath, &st) == 0);
}

ResourceBundle loadResourceBundle(const char *filepath, size_t concurrent_requests, void (*callback)(const Metadata *metadata)) {
    ResourceBundle rb = {0};
    strcpy(rb.filepath, filepath);
    rb.concurrent_requests = concurrent_requests;

    if (!file_exists(filepath)) {
        perror("Error: File does not exist.");
        return rb;
    }

    CURLcode res;
    char *file_content = NULL;
    size_t file_content_size;
    struct curl_slist *header_list = NULL;
    CURL *curl = curl_easy_init();

    if (curl) {
        header_list = curl_slist_append(header_list, "User-Agent: MyApp/1.0");

        res = curl_easy_setopt(curl, CURLOPT_URL, filepath);
        if (res != CURLE_OK) {
            perror("Error setting URL.");
            goto cleanup;
        }

        res = curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        if (res != CURLE_OK) {
            perror("Error setting write callback.");
            goto cleanup;
        }

        res = curl_easy_setopt(curl, CURLOPT_WRITEDATA, &rb);
        if (res != CURLE_OK) {
            perror("Error setting write data callback.");
            goto cleanup;
        }

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            perror("Error performing request.");
            goto cleanup;
        }

        file_content = rb.metadata[0]->value;
        file_content_size = rb.num_items * json_object_get_length(rb.metadata[0]);
    } else {
        perror("Error initializing curl.");
        goto cleanup;
    }

cleanup:
    curl_easy_cleanup(curl);
    curl_slist_free_all(header_list);

    if (file_content) {
        for (size_t i = 0; i < rb.num_items; ++i) {
            callback(rb.metadata[i]);
        }

        pthread_mutex_init(&rb.mutex, NULL);

        for (size_t i = 0; i < rb.concurrent_requests; ++i) {
            pthread_t thread;
            ResourceBundle *thread_rb = &rb;

            if (pthread_create(&thread, NULL, validate_integrity, thread_rb) != 0) {
                perror("Error creating thread.");
            }
        }
    }

    return rb;
}

void *validate_integrity(void *arg) {
    ResourceBundle *rb = (ResourceBundle *)arg;

    // Implement API call to validate file integrity.
    // If the validation fails, log error and exit gracefully.

    pthread_exit(NULL);
}
```
