using CircularBuffer = boost::circular_buffer<DataMap>;

constexpr int MAX_CONCURRENT_REQUESTS = std::getenv("MAX_CONCURRENT_REQUESTS") ? std::stoi(std::getenv("MAX_CONCURRENT_REQUESTS")) : 10;
constexpr int RATE_LIMIT_PERIOD_MS = std::getenv("RATE_LIMIT_PERIOD_MS") ? std::stoi(std::getenv("RATE_LIMIT_PERIOD_MS")) : 1000;
const char* DIRECTORY_PATH = std::getenv("DIRECTORY_PATH");
