void loadResourceBundle(const fs::path& directoryPath) {
    CircularBuffer buffer(MAX_CONCURRENT_REQUESTS);
    boost::asio::io_service ios;
    boost::asio::ip::tcp::resolver resolver(ios);

    auto rateLimitSemaphore = std::make_shared<boost::mutex>();
    int requestCount = 0;
    sigev_t signalHandler;
    memset(&signalHandler, 0, sizeof(signalHandler));
    signalHandler.sigev_notify = SIGEV_THREAD;

    struct kevent event;
    constexpr int kqueueFD = std::atoi(getenv("KQUEUE_FD"));
    KQ_INIT(&event);
    KQFILTER(EVFILT_TIMER, EV_ADD);
    struct timespec ts = {RATE_LIMIT_PERIOD_MS / 1000, (RATE_LIMIT_PERIOD_MS % 1000) * 1e6};
    event.itimerspec = ts;
    kevent(kqueueFD, &event, nullptr, nullptr, nullptr);

    auto onSignalHandler = [](int signal, siginfo_t*, void* userData) {
        auto& semaphore = *static_cast<std::shared_ptr<boost::mutex>*>(userData);
        std::unique_lock<decltype(semaphore->lock())> lock(semaphore->scoped_lock());
        if (requestCount < MAX_CONCURRENT_REQUESTS) {
            ++requestCount;
            lock.unlock();
        }
    };

    signal(SIGUSR1, onSignalHandler, reinterpret_cast<void*>(&rateLimitSemaphore));

    for (const auto& entry : fs::recursive_directory_iterator(directoryPath)) {
        if (entry.is_regular_file() && entry.path().extension() == ".data") {
            std::unique_ptr<json_t> jsonData(json_loads(fs::file_to_string(entry).c_str(), JSON_DECREF, nullptr));
            if (!jsonData) continue;

            DataMap dataMap{{"path", fs::absolute(entry.path()).string().c_str()}, {"data", *jsonData}};
            buffer.push_back(std::move(dataMap));
        }
    }

    auto currentIndex = 0;
    while (true) {
        if (requestCount >= MAX_CONCURRENT_REQUESTS) continue;

        DataMap& dataMap = buffer[currentIndex % MAX_CONCURRENT_REQUESTS];
        const std::string& schemaPath = dataMap["data"]->child("schema").get_string();
        const fs::path schemaFile(DIRECTORY_PATH / schemaPath);
