import { promisify } from 'util';
import cache from 'memory-cache';
import chalk from 'chalk';
import Bluebird from 'bluebird';
import lodash from 'lodash';
import axios from 'axios';

const log = (message, level = 'info') => console.log(chalk[level](`${new Date().toISOString()}: ${message}`));

class TestRunner {
  constructor({ externalServices, loggingService, maxConcurrency }) {
    this.externalServices = externalServices;
    this.loggingService = loggingService;
    this.maxConcurrency = maxConcurrency;
  }

  async loadLib(moduleName) {
    const moduleCacheKey = `lib_${moduleName}`;
    let module;
    if (cache.get(moduleCacheKey)) {
      log(`Loaded from cache: ${moduleCacheKey}`);
      module = cache.get(moduleCacheKey);
    } else {
      try {
        const libModule = await import(`./libs/${moduleName}`).then(({ default: lib }) => lib);
        cache.put(moduleCacheKey, libModule, 60 * 60 * 24); // Cache for 1 day
        log(`Loaded from disk: ${moduleCacheKey}`);
        module = libModule;
      } catch (error) {
        log(`Error loading library: ${moduleName}`, 'error');
        throw error;
      }
    }
    return module;
  }

  async executeTests() {
    const promises = this.externalServices.map(async ({ name, url }) => {
      try {
        log(`Starting test: ${name}`);
        const results = await this.runTest(name, url);
        return results;
      } catch (error) {
        log(`Error executing test: ${name}`, 'error');
        throw error;
      }
    });

    const concurrentRunner = Bluebird.map(promises, this.throttleWrapper(this.maxConcurrency), { concurrency: this.maxConcurrency });
    return await concurrentRunner;
  }

  throttleWrapper(concurrency) {
    return async (promise) => {
      const activePromises = new Set();
      let activeCount = 0;
      return promisify(cb => {
        if (activeCount === concurrency) return;
        activePromises.add(cb);
        activeCount++;
        promise().then(() => {
          activePromises.delete(cb);
          activeCount--;
        });
      });
    };
  }

  async runTest(testName, testUrl) {
    // Implement mocking strategy using blueslip and external service call using axios
  }

  async logResults(results) {
    await Promise.all(results.map(async result => {
      const { name, status, duration, logEvents } = result;
      if (status === 'pass') {
        log(`Test ${name} passed`, 'green');
      } else {
        log(`Test ${name} failed`, 'red');
      }
      await this.loggingService.log(name, status, duration, logEvents);
    }));
  }

  async generateReport() {
    // Generate comprehensive summary report post-execution
  }
}

