function extractIds(id) {
  const match = id.match(ID_REGEX);
  return match ? [match[1], match[2]] : null;
}

function isValidJson(json) {
  try {
    JSON.parse(json);
    return true;
  } catch (e) {
    return false;
  }
}

function parseBookOccurrences(content) {
  const books = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', 'Isaiah', 'Jeremiah', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
  const regex = new RegExp(`\\b(${books.join('|')})\\b`, 'ig');
  const matches = content.match(regex);
  const frequencies = _.countBy(matches || []);
  return frequencies;
}

function refreshDialogFields(id) {
  const [sectionId, elementId] = extractIds(id);

  if (!CACHE[sectionId]) {
    CACHE[sectionId] = {};
  }

  if (CACHE[sectionId][elementId]) {
    return Promise.resolve(CACHE[sectionId][elementId]);
  }

  const url = `${API_URL}/sections/${sectionId}/elements/${elementId}`;
  return axios.get(url)
    .then((response) => {
      if (isValidJson(response.data)) {
        CACHE[sectionId][elementId] = response.data;
        const content = parseBookOccurrences(response.data.content);
