     ```cpp
     #include <boost/asio.hpp>
     // ...
     std::atomic<int> ref_count_{0};
     Transaction* operator new(size_t size) {
         if (!pool_.empty()) {
             auto transaction = pool_.front();
             pool_.pop_front();
             transaction->ref_count_ = 1;
             return transaction;
         }
         return ::operator new(size);
     }
     // ...
     Transaction* operator delete(Transaction * p) noexcept {
         if (--p->ref_count_ == 0) {
             pool_.push_back(p);
             p = nullptr;
         }
         return ::operator delete(p);
     }
