// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t size;
} Array;

// Function to create and initialize an array with a specified size
Array* array_create(size_t initial_size) {
    Array* arr = malloc(sizeof(Array));
    if (!arr) error("Failed to allocate memory for array");

    arr->elements = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->elements) error("Failed to allocate memory for array elements");

    arr->capacity = initial_size;
    arr->size = 0;
    return arr;
}

// Function to append an element to the array
void array_append(Array* arr, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (arr->size >= arr->capacity) {
        arr->elements = realloc(arr->elements, (arr->capacity + 1024) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!arr->elements) error("Failed to reallocate memory for array elements");
        arr->capacity += 1024;
    }

    memcpy(&arr->elements[arr->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size++;
}

// Function to get an element from the array by index (thread-safe)
const NFAPI_CRC_INDICATION_PDU_T* array_get(Array* arr, size_t index) {
    pthread_mutex_lock(&mutex);

    if (index >= arr->size || index < 0) {
        error("Invalid index");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    const NFAPI_CRC_INDICATION_PDU_T* res = &arr->elements[index];
    pthread_mutex_unlock(&mutex);
    return res;
}

// Function to free the array and its elements (thread-safe)
void array_free(Array* arr) {
    pthread_mutex_lock(&mutex);

    if (arr->elements) free(arr->elements);
    free(arr);

    pthread_mutex_unlock(&mutex);
}

