[' Here's a high-level design for your requested system in C#:

```csharp
public class SemaphoreService
{
    private ConcurrentDictionary<string, SemaphoreSlim> _semaphores;
    private readonly RandomValueGenerator _valueGenerator;

    public SemaphoreService(RandomValueGenerator valueGenerator)
    {
        _valueGenerator = valueGenerator;
        _semaphores = new ConcurrentDictionary<string, SemaphoreSlim>();
    }

    public void AddSemaphore(string key, int initialValue)
    {
        _semaphores[key] = new SemaphoreSlim(initialValue);
    }

    public void RemoveSemaphore(string key)
    {
        if (_semaphores.TryRemove(key, out var semaphore))
            semaphore.Dispose();
    }

    public void ModifySemaphore(string key, Action<int> setValue)
    {
        if (_semaphores.TryGetValue(key, out var semaphore))
        {
            lock (semaphore)
            {
                setValue((int)Math.Min(10000, Math.Max(0, semaphore.CurrentValue + _valueGenerator.RandomInt())));
            }
        }
    }

    // Acquire and release methods for the Semaphores
}

public class RandomValueGenerator
{
    private readonly int _min;
    private readonly int _max;

    public RandomValueGenerator(int min, int max)
    {
        _min = min;
        _max = max;
    }

    public int RandomInt() => new Random().Next(_min, _max);

    public float RandomFloat() => (float)(_valueGenerator.RandomInt() + 1) / (_max - _min + 2);

    public override string ToString() => $"({_min}, {_max})";
}
```

