const renderFooterScripts = (configs) => {
  const scriptTags = configs.map((config) => {
    const { src, type, defer, async } = config;
    return `<script src="${src}" type="${type}" ${defer ? 'defer' : ''} ${async ? 'async' : ''}> </script>`;
  });

  // Replace placeholders in the footer template with script tags
  const footerTemplate = document.getElementById('footer-template');
  const footerHtml = footerTemplate.innerHTML
    .replace(/%SCRIPT_TAGS%/g, scriptTags.join(''));

  // Render the footer section
  const footer = document.createElement('footer');
  footer.innerHTML = footerHtml;
  document.body.appendChild(footer);
};
