```

2. Implement the Triple DES decryption function in a source file, e.g., `TripleDES.cpp`:

```cpp
#include "Messenger.h"
#include <openssl/aes.h>
#include <sstream>
#include <base64.hpp // Use your preferred Base64 library

namespace {
    AES_KEY aesKey;
    void setupTripleDES(const std::string& key, const std::string& iv) {
        AES_keygen(reinterpret_cast<unsigned char*>(aesKey.buf), &aesKey.length, key.c_str(), iv.c_str(), AES_KEYGEN_LEN128);
    }
}

std::string Messenger::decryptBase64EncodedTripleDES(const std::string& encryptedMessage, const std::string& key, const std::string& iv) {
    if (encryptedMessage.empty()) return "";
    uint8_t encryptedData[encryptedMessage.length()];
    if (!base64_decode((const unsigned char*)encryptedMessage.c_str(), &encryptedData)) return "";
    setupTripleDES(key, iv);
    constexpr size_t blockSize = AES_BLOCK_SIZE;
    std::vector<uint8_t> decryptedData(encryptedMessage.size() + (encryptedMessage.size() / blockSize) + 1);
    const size_t numBlocks = encryptedMessage.size() / blockSize + (encryptedMessage.size() % blockSize > 0 ? 1 : 0);
    for (size_t i = 0; i < numBlocks; ++i) {
        AES_decrypt(reinterpret_cast<unsigned char*>(encryptedData + i * blockSize), reinterpret_cast<unsigned char*>(decryptedData.data() + i * blockSize), &aesKey);
    }
    return std::string(reinterpret_cast<char*>(decryptedData.data()), decryptedData.size());
}
```']

