// Helper function using UnionFind
fn find_common_ancestor(a: &Path, b: &Path) -> Option<PathBuf> {
    let mut uf = UnionFind::new();
    for dir in a.ancestors() {
        uf.insert(*dir);
    }
    for dir in b.ancestors() {
        if let Some(parent) = uf.find(&**dir) {
            return Some(parent.into());
        }
    }
    None
}
