int Octree::executeCommand() {
    char** arguments;
    int status;
    unique_ptr<char[]> commandWithPath(new char[_command.size() + _filePath.size() + 1]);
    std::copy(_command.begin(), _command.end(), commandWithPath.get());
    std::copy(_filePath.begin(), _filePath.end(), commandWithPath.get() + _command.size());
    commandWithPath[_command.size() + _filePath.size()] = '\0';

    arguments = new char*[2];
    arguments[0] = const_cast<char*>(commandWithPath.get());
    arguments[1] = nullptr;

    File file(_filePath);
    if (!file.exists()) {
        cerr << "Error: The specified file does not exist." << endl;
        return -1;
    }

    pid_t childPid = fork();
    if (childPid == -1) {
        cerr << "Error: Fork failed." << endl;
        return -1;
    } else if (childPid > 0) { // Parent process
        int status;
        waitpid(childPid, &status, 0);
        return WEXITSTATUS(status);
    } else { // Child process
        execv(arguments[0], arguments);
        cerr << "Error: Command execution failed." << endl;
        handleErrors();
        exit(-1);
    }
}

void Octree::handleErrors() {
    void* array[10];
    size_t size = backtrace(array, 10);
    char** symbols = backtrace_symbols(array, size);

    cerr << "Error trace:\n";
    for (size_t i = 0; i < size; ++i) {
        cerr << symbols[i] << "\n";
    }
    free(symbols);
}

Octree::Octree(int featureSize, int numLeafNodes, int dataCapacity, const string& command, const string& filePath) :
    _featureSize(featureSize), _numLeafNodes(numLeafNodes), _dataCapacity(dataCapacity), _command(command), _filePath(filePath) {
}

bool Octree::initialize() {
    if (!_root.get()) {
        try {
            populateOctree();
        } catch (const exception& e) {
            cerr << "Error: " << e.what() << endl;
            return false;
        }

        int commandStatus = executeCommand();
        if (commandStatus != 0) {
            cerr << "Error: Command execution failed with status code " << commandStatus << endl;
            handleErrors();
            return false;
        }
    }

    // Return success status or any warnings encountered during setup.
}
