#include <csignal>
#include <openssl/sha.h>
#include <cstdio>
#include <curl/curl.h>
#include <boost/log/trivial.hpp>
#include <boost/asio/io_service.hpp>
#include <boost/date_time/posix_time/ptime.hpp>

struct Transaction {
    std::string user_id;
    double amount;
    int recent_average_count = 0;
    double recent_average = 0.0;
    boost::posix_time::ptime timestamp;
};

class FraudDetector {
public:
    virtual bool detectFraud(const Transaction& transaction) const = 0;
    virtual ~FraudDetector() {}
};

class LocalFraudDetector : public FraudDetector {
public:
    bool detectFraud(const Transaction& transaction) const override {
        // Your custom fraud detection logic here...
        return false;
    }
};

class ExternalFraudDetector : public FraudDetector {
private:
    std::string api_key_;
    CURL* curl_;

public:
    ExternalFraudDetector(const std::string& api_key) : api_key_(api_key), curl_(curl_easy_init()) {}

    bool detectFraud(const Transaction& transaction) const override {
        if (!curl_) {
            // Handle initialization errors...
        }

        CURLcode res;
        std::stringstream payload;
        payload << "user_id=" << transaction.user_id
                << "&amount=" << transaction.amount
                << "&api_key=" << api_key_;

        res = curl_easy_setopt(curl_, CURLOPT_URL, "https://fraud-detection-api.com/detect");
        res = curl_easy_setopt(curl_, CURLOPT_POSTFIELDS, payload.str().c_str());
        res = curl_easy_perform(curl_);

        if (res != CURLE_OK) {
            // Handle API errors...
        }

        int fraud;
        res = curl_easy_getinfo(curl_, CURLINFO_RESPONSE_CODE, &fraud);
        if (res != CURLE_OK || fraud == 401) {
            // Handle API errors...
        }

        return fraud > 0;
    }
};

class TransactionProcessor {
private:
    std::vector<Transaction> transactions_;
    FraudDetector* fraud_detector_;
    boost::log::trivial::logger logger_;

public:
    TransactionProcessor(FraudDetector* detector) : fraud_detector_(detector), logger_(boost::log::trivial::get("transaction")) {}

    void processTransaction(const std::string& line, const std::string& filename) {
        std::istringstream iss(line);
        if (!std::getline(iss, transactions_.front().user_id)) {
            logger_.error("Missing user_id in {}", filename);
            return;
        }

        double amount = 0.0;
        bool has_amount = false;
        std::string field;
        while (std::getline(iss, field, ',')) {
            if (field == "") continue;
            if (!has_amount) {
                try {
                    amount = std::stod(field);
                    has_amount = true;
                } catch (const std::exception& e) {
                    logger_.error("Invalid amount in {}, {}", filename, field);
                    return;
                }
            } else {
                if (iss.peek() == ',') {
                    iss.ignore();
                } else {
                    logger_.error("Extra comma in {}", filename);
                    return;
                }
            }
        }

        if (!has_amount) {
            logger_.error("Missing amount in {}", filename);
            return;
        }

        transactions_.front().amount = amount;
        transactions_.front().timestamp = boost::posix_time::second_clock::local_time();
        ++transactions_.begin()->recent_average_count;
        transactions_.front().recent_average = std::accumulate(
            std::next(transactions_.begin()), std::prev(transactions_.end()),
            0.0,
            [this](double sum, const Transaction& transaction) {
                if (transaction.user_id == transactions_.front().user_id) {
                    sum += transaction.amount;
                }
                return sum;
            }
        ) / transactions_.front().recent_average_count;

        if (!fraud_detector_->detectFraud(transactions_.front())) {
            // Process further or store the transaction...
        } else {
            logger_.info("Detected fraud for {}", transactions_.front().user_id);
        }
    }

    void processFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            logger_.error("Cannot open file {}", filename);
            return;
        }

        Transaction new_transaction;
        transactions_.push_back(new_transaction);
        std::string line;
        while (std::getline(file, line)) {
            processTransaction(line, filename);
            transactions_.pop_back();
            if (transactions_.empty()) {
                transactions_.push_back(new_transaction);
            }
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " API_KEY CSV1 [CSV2 ...]" << std::endl;
        return -1;
    }

    std::string api_key(argv[1]);
    FraudDetector* fraud_detector = new ExternalFraudDetector(api_key);
    TransactionProcessor processor(fraud_detector);

    boost::asio::io_service io_service;
    std::vector<std::future<void>> file_handles;
    for (int i = 2; i < argc; ++i) {
        file_handles.push_back(std::async(std::launch::async,
            [&io_service, &processor, argv[i]]() mutable {
                processor.processFile(argv[i]);
            }, io_service));
    }

    io_service.run();

    for (auto& handle : file_handles) {
        handle.wait();
    }

    delete fraud_detector;
    return 0;
}
```

