[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <time.h>

/* External data source callback function */
typedef void (*ue_info_callback)(unsigned long rnti, unsigned int crcflag);

/* UE information structure */
typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

/* Thread-safe memory pool for NFAPI_CRC_INDICATION_PDU_T structures */
struct mem_pool {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

/* Initialize memory pool with given capacity */
void init_mem_pool(struct mem_pool *mp, size_t capacity) {
    mp->capacity = capacity;
    mp->count = 0;
    mp->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->data) {
        fprintf(stderr, "Failed to allocate memory for mem pool\n");
        exit(1);
    }
    pthread_mutex_init(&mp->lock, NULL);
}

/* Free memory pool resources */
void free_mem_pool(struct mem_pool *mp) {
    if (mp->data) {
        free(mp->data);
        mp->data = NULL;
    }
    pthread_mutex_destroy(&mp->lock);
}

/* Allocate an NFAPI_CRC_INDICATION_PDU_T structure from the memory pool, returning NULL if pool is empty */
NFAPI_CRC_INDICATION_PDU_T* mem_pool_alloc(struct mem_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count < mp->capacity) {
        mp->count++;
        pthread_mutex_unlock(&mp->lock);
        return &mp->data[mp->count - 1];
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL;
}

/* Return an NFAPI_CRC_INDICATION_PDU_T structure to the memory pool */
void mem_pool_free(struct mem_pool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mp->lock);
    if (pdu >= mp->data && pdu < &mp->data[mp->capacity]) {
        mp->count--;
        pthread_mutex_unlock(&mp->lock);
    } else {
        fprintf(stderr, "Invalid NFAPI_CRC_INDICATION_PDU_T pointer\n");
        exit(1);
    }
}

/* Multi-threaded function to populate the array of structures */
void populate_ue_info_array(size_t num_ues, struct mem_pool *mem_pool, ue_info_callback callback) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    unsigned long seed = (unsigned long)current_time.tv_nsec | ((unsigned long)current_time.tv_sec << 32);

    for (size_t i = 0; i < num_ues; ++i) {
        pdu = mem_pool_alloc(mem_pool);
        if (!pdu) {
            fprintf(stderr, "Failed to allocate memory for UE %zu\n", i);
            continue;
        }

        pdu->RX_UE_INFORMATION_TAG = seed + i;
        pdu->RNTI = (i << 16) | i; // Example: assign RNTI based on index to illustrate the concept
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

        if (callback) {
            callback(pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
        }
    }
}

// Main function to run the multi-threaded population process
int main(int argc, char **argv) {
    size_t num_ues = 1024; // Number of UE instances
    struct mem_pool mem_pool;
    ue_info_callback callback = /* Your external data source callback function here */;

    if (argc > 1) {
        num_ues = atoi(argv[1]);
    }

    init_mem_pool(&mem_pool, num_ues);
    populate_ue_info_array(num_ues, &mem_pool, callback);
    free_mem_pool(&mem_pool);

    return 0;
}
