```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double *data;
    size_t length;
} TimeSeries;

TimeSeries *load_time_series(const char *filepath) {
    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t length = ftell(file) / sizeof(double);
    rewind(file);

    TimeSeries *ts = (TimeSeries *)malloc(sizeof(TimeSeries));
    if (!ts) {
        perror("Error allocating memory for TimeSeries");
        return NULL;
    }

    ts->data = malloc(length * sizeof(double));
    if (!ts->data) {
        free(ts);
        perror("Error allocating memory for time series data");
        return NULL;
    }

    if (fread(ts->data, length * sizeof(double), 1, file) != 1) {
        perror("Error reading file");
        free(ts);
        return NULL;
    }

    ts->length = length;
    fclose(file);
    return ts;
}

void autocorrelation(TimeSeries *ts, int lags, double **autocorr) {
