```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int execute_command(const char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp");
        _exit(1);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) ? WEXITSTATUS(status) : 0;
    }
}
```

