['1. SemaphoreService (High-Concurrency, Thread-Safe Semaphore Manager):

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public class SemaphoreService : ISemaphoreService
{
    private readonly ILogger<SemaphoreService> _logger;
    private readonly IOptionsMonitor<SemaphoreOptions> _options;
    private readonly ConcurrentDictionary<int, SemaphoreSlim> _semaphores = new();

    public SemaphoreService(ILogger<SemaphoreService> logger, IOptionsMonitor<SemaphoreOptions> options)
    {
        _logger = logger;
        _options = options;
        InitializeSemaphoresAsync().Wait();
    }

    private async Task InitializeSemaphoresAsync()
    {
        var semaphoreRange = _options.CurrentValue.Range;
        for (int i = semaphoreRange.Minimum; i <= semaphoreRange.Maximum; i++)
            await AddSemaphoreAsync(i);
    }

    public async Task AddSemaphoreAsync(int id, int value = 1) => await AddOrUpdateSemaphoreAsync(id, semaphore => semaphore.Value += value);
    public async Task RemoveSemaphoreAsync(int id, int value = 1) => await AddOrUpdateSemaphoreAsync(id, semaphore => semaphore.Value -= value);
    public async Task ModifySemaphoreAsync(int id, Func<SemaphoreSlim, SemaphoreSlim> modifier) => await UpdateSemaphoreAsync(id, modifier);

    private async Task AddOrUpdateSemaphoreAsync(int id, Func<SemaphoreSlim, SemaphoreSlim> modifier)
    {
        if (!_semaphores.TryAdd(id, new SemaphoreSlim(1, 1)))
            await UpdateSemaphoreAsync(id, modifier);
    }

    private async Task UpdateSemaphorAsync(int id, Func<SemaphoreSlim, SemaphoreSlim> modifier)
    {
        _semaphores.GetOrAdd(id, new SemaphoreSlim(1, 1)).Wait();

        if (_semaphores[id].Value <= 0)
            throw new InvalidOperationException("Attempted to modify a non-existent or empty semaphore.");

        var semaphore = _semaphores[id];
        semaphore.Wait();

        try
        {
            semaphore = modifier(semaphore);
            semaphore.Release();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating a semaphore.");
            semaphore.Release();
            throw;
        }
    }
}
```

