public class RandomValueGenerator
{
    public int NextInt(int minInclusive, int maxExclusive) => new Random().Next(minInclusive, maxExclusive);
    public float NextFloat(float minInclusive, float maxExclusive) => (float)(new Random().NextDouble() * (maxExclusive - minInclusive) + minInclusive);

    public override string ToString() => $"[{Nameof(NextInt)}: {Nameof(minInclusive)}, {Nameof(maxExclusive)}], [{Nameof(NextFloat)}: {Nameof(minInclusive)}, {Nameof(maxExclusive)}]";
}
```

