mod failure_handling {
    use super::*;

    async fn retry<F>(func: F, max_retries: u32, delay: Duration) -> Result<(), Box<dyn std::error::Error> >
    where
        F: FnOnce() -> Result<(), Box<dyn std::error::Error>>,
    {
        let mut attempts = AtomicUsize::new(0);
        loop {
            match func().await {
                Ok(_) => return Ok(()),
                Err(e) if attempts.load(Ordering::Relaxed) >= max_retries => {
                    return Err(Box::new(e))
                }
                Err(e) => {
                    let sleep_duration = Instant::now() + delay;
                    tokio::time::sleep(sleep_duration - Instant::now()).await;
                    attempts.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
    }
}

