// Forward List Manipulation Function
void insertAfter(std::list<std::string>& list, const std::string& firstArg, const std::string& secondArg) {
    auto it = list.begin();
    if (it != list.end() && *it == firstArg) {
        it = std::next(it);
        list.insert(it, secondArg);
    } else {
        list.push_back(secondArg);
    }
}
