import json
from typing import Dict, Type, Callable

class JSONObject:
    _factories = {}

    @staticmethod
    def register(factory_id: str, factory: Callable[[Dict], Type['JSONObject']]):
        JSONObject._factories[factory_id] = factory

    @staticmethod
    def from_json(json_str: str, factory_id: str = None) -> 'JSONObject':
        if factory_id is not None:
            return JSONObject._factories[factory_id](json.loads(json_str))

        for factory in JSONObject._factories.values():
            try:
                return factory(json.loads(json_str))
