For the C function `computeChecksumList`, you can leverage existing libraries like OpenSSL or libsodium for cryptographic integrity and reliability:

```c
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned char checksum[SHA256_DIGEST_LENGTH];
} Checksum;

Checksum* computeChecksumList(const char** filenames, size_t numFiles) {
    // Initialize a SHA-256 context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    Checksum* checksums = malloc(numFiles * sizeof(Checksum));
    for (size_t i = 0; i < numFiles; ++i) {
        // Compute the hash of each file and store it in a buffer
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
            perror("Error opening file");
            continue;
        }

        uint8_t buffer[SHA256_BLOCK_SIZE];
        size_t bytesRead;
        while ((bytesRead = fread(buffer, sizeof(buffer), 1, file)) > 0) {
            SHA256_Update(&ctx, buffer, bytesRead);
        }
        fclose(file);

        // Finalize the hash computation and store it in the checksum array
        SHA256_Final(checksums[i].checksum, &ctx);
    }

    return checksums;
}
```']

