C function for computing checksums:

```c
#include <stdio.h>
#include <openssl/sha.h>
#include <string.h>

typedef struct {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    size_t length;
} SHA256_CTX;

void computeChecksumList(const char **files, size_t count, unsigned long long *checksums) {
    SHA256_CTX ctx;
    unsigned i, j;

    memset(&ctx, 0, sizeof(SHA256_CTX));

    for (i = 0; i < count; ++i) {
        // Initialize context with the first file
        if (!i) {
            SHA256_Init(&ctx);
            SHA256_Update(&ctx, files[i], strlen(files[i]));
            continue;
        }

        // Combine checksums of previous files and current file
        unsigned char combined[SHA256_DIGEST_LENGTH];
        memcpy(combined, checksums[i - 1], SHA256_DIGEST_LENGTH);
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, files[i], strlen(files[i]));
        SHA256_Update(&ctx, combined, SHA256_DIGEST_LENGTH);

        // Update checksums for the current file
        SHA256_Final(checksums[i] = ctx.digest, &ctx);
    }
}
```']

