```c
#include <stdarg.h>
#include <stdio.h>
#include <time.h>

void logCondition(const char* level, const char* message, ...) {
    static char log_buffer[4096];
    time_t now;
    struct tm* tstruct;
    FILE* fp;

    if ((fp = fopen("error.log", "a")) == NULL) return;

    time(&now);
    tstruct = localtime(&now);

    snprintf(log_buffer, sizeof(log_buffer), "[%04d-%02d-%02d %02d:%02d:%02d] [%s] %s\n",
            1900 + tstruct->tm_year, 1 + tstruct->tm_mon, tstruct->tm_mday,
            tstruct->tm_hour, tstruct->tm_min, tstruct->tm_sec, level, message);

    va_list args;
    va_start(args, message);
    vfprintf(fp, log_buffer + strlen(log_buffer), args);
    va_end(args);

    fclose(fp);
}
```

