```cpp
int retryDatabaseOperation(const std::function<int()>& operation) {
    const int maxRetries = 5;
    const int backoffMultiplier = 2;
    int retries = 0;

    for (;;) {
        int result = operation();
        if (result == 0) return 0; // Success, no need to retry

        std::this_thread::sleep_for(std::chrono::milliseconds(retries * backoffMultiplier));
        retries++;
        if (retries >= maxRetries) throw std::runtime_error("Maximum number of retries exceeded");
    }
}
