class DataProcessorFactory:
    @staticmethod
    async def create(config: Dict[str, Any]):
        sources = []
        sinks = []
        adapters = []
        for source_config in config["sources"]:
            if "adapter" not in source_config:
                sources.append(SourceFactory.create(source_config))
            else:
                adapter_config, source_config = source_config["adapter"], source_config["source"]
                adapters.append(AdapterFactory.create(adapter_config))
                sources.append(adapters[-1].source)

        for sink_config in config["sinks"]:
            sinks.append(SinkFactory.create(sink_config))

        return DataProcessor(sources, sinks, **config["params"])

