**loadResourceBundle function in C#:**

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;

public async Task<string> LoadResourceBundle(string directoryPath)
{
    var filePaths = Directory.GetFiles(directoryPath, "*.json");
    var items = new List<Item>();

    foreach (var filePath in filePaths)
    {
        using (var reader = File.OpenText(filePath))
        {
            var json = await reader.ReadToEndAsync();
            items.AddRange(JsonConvert.DeserializeObject<IEnumerable<Item>>(json));
        }
    }

    return $"Total Items: {items.Count}\n{string.Join("\n", items.Select(item => item.ToString()))}";
}

public class Item
{
    public string Id { get; set; }
    public DateTimeOffset Timestamp { get; set; }
    // Other properties as needed

    public override string ToString()
    {
        return $"ID: {Id}\nTimestamp: {Timestamp.ToString("o")}";
    }
}
```']

