      if (validateCRL(response.data)) {
        resolve();
      } else {
        reject(new Error('Invalid CA certificate'));
      }
    } catch (error) {
      reject(error);
    }
  });
}

function caCertAgent(caId) {
  return new request.Agent({
    ca: fs.readFileSync(`./certificates/${caId}.pem`), // Replace with actual path to CA certificates
    maxSockets: 1, // Use a single socket per CA to optimize performance
  });
}

function validateCRL(crl) {
