For the byte copying function, named `copy_bytes`, you can use the `Buffer` type from the Rust standard library and create an inlinable function:

```rust
// src/lib.rs
use std::mem;

fn copy_bytes(bufs: &[&[u8]], len: usize) -> Vec<u8> {
    let mut dest = Vec::with_capacity(len);
    dest.set_len(len);
    unsafe {
        let dest_ptr = dest.as_mut_ptr();
        mem::copy_nonoverlapping(
            bufs.iter().flat_map(|buf| buf.as_ptr()).chain(bufs.last().and_then(|buf| buf.add(buf.len()) as *const u8), dest_ptr, len);
    }
    dest
}
```

