        await Cache.LockTakeAsync(lockKey, dbTime: TimeSpan.FromMinutes(1));

        try
        {
            // Acquired the lock, update the user now
            await UpdateUserInCacheAndDatabase(userId, user);
        }
        finally
        {
            Cache.LockRelease(lockKey);
        }
    }
}
