        // Apply validation and byte constraints here

        pthread_mutex_lock(&lock);
        processExternalIntegration((BufferChunk){ .data = validatedData, .length = dataChunks[i].length });
        free(validatedData);
        pthread_mutex_unlock(&lock);
    }

    return true;
}
