5. C function `computeChecksumList` for computing unique checksums:

```c
#include <stdio.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct {
    char filename[256];
    unsigned char checksum[SHA256_DIGEST_LENGTH];
} ChecksumListEntry;

void computeChecksumList(const char* dir, ChecksumListEntry** list, size_t* len) {
    DIR *d = opendir(dir);
    struct dirent *de;
    SHA256_CTX ctx;
    ChecksumListEntry entry;
    int i = 0;

    if (d != NULL) {
        while ((de = readdir(d)) != NULL) {
            if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0)
                continue;

            snprintf(entry.filename, sizeof(entry.filename), "%s/%s", dir, de->d_name);

            SHA256_Init(&ctx);
            FILE *fp = fopen(entry.filename, "rb");
            if (fp != NULL) {
                uint8_t buffer[4096];
                size_t bytesRead;

                while ((bytesRead = fread(buffer, sizeof(buffer), 1, fp)) > 0) {
                    SHA256_Update(&ctx, buffer, bytesRead);
                }

                fclose(fp);
                SHA256_Final(entry.checksum, &ctx);
            }

            if (i == *len) {
                (*len) += 10; // Resize the array
                entry.filename[sizeof(entry.filename) - 1] = '\0'; // Ensure null-terminated strings
                list[i] = realloc(list, sizeof(ChecksumListEntry)*(*len));
            }

            list[i++] = &entry;
        }
        closedir(d);
    } else {
        perror("opendir");
    }
}
```']

