        // Validate password input (min length, character types)
        if (!preg_match('/(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{12,}/', $newPassword)) {
            return response('400', 'Invalid password format');
        }

        try {
            $apiResponse = $this->apiService->validatePasswordStrength($newPassword);

            if ($apiResponse['status'] !== 200) {
                // Handle external service errors gracefully
                return response('503', 'Temporary service outage');
            }

            // Update password in the database with connection pooling
            // ...

            $this->redis->enqueuePasswordUpdateTask($userId);

            $this->emailService->sendPasswordChangeConfirmationEmail($userId);

            return response('200', 'Password updated successfully');
        } catch (Exception $e) {
            if (strpos($e->getMessage(), 'Rate limit exceeded') !== false) {
                // Handle rate limits and retry logic for external service calls
                sleep(pow(2, $this->getRetryAttempt()) * $apiService->getBackoffTime());
                return $this->updateUserPassword($userId, $newPassword);
