```javascript
class ModuleLoader {
    constructor() {
        this.scriptTags = document.getElementsByTagName('script');
        this.loadedScripts = new Set();
        this.pendingScripts = new Map();
        this.onLoadCallbacks = [];
        this.onErrorCallbacks = [];
    }

    load(url) {
        if (this.loadedScripts.has(url)) return;

        const script = document.createElement('script');
        script.src = url;
        script.async = true;

        script.onload = () => {
            this.loadedScripts.add(url);
            this.executeOnLoadCallbacks(url);
        };

        script.onerror = () => {
            this.loadedScripts.add(url);
            this.executeOnErrorCallbacks(url);
        };

        document.head.appendChild(script);
    }

    executeOnLoadCallbacks(url) {
        for (const callback of this.onLoadCallbacks[url]) {
            callback();
        }
    }

    executeOnErrorCallbacks(url) {
        for (const callback of this.onErrorCallbacks[url]) {
            console.error('Script error: ' + callback());
        }
    }

    // Add methods to handle asynchronous loading, script errors, and lazy loading of non-critical scripts
}
```"]

