class SIM_Manager {
private:
    std::vector<std::shared_ptr<SIM_Module>> sims_;
    std::mutex sims_mutex_;
    std::queue<LTE_MME_MESSAGE_T> messageQueue_;

public:
    void addSIM(const std::shared_ptr<SIM_Module>& sim) {
        std::unique_lock<std::mutex> lock(sims_mutex_);
        sims_.push_back(sim);
    }

    // Asynchronously processes messages and distributes them to the appropriate SIM modules.
    void processMessages() {
        while (true) {
            std::unique_lock<std::mutex> lock(messageQueue_.mutex());
            if (!messageQueue_.empty()) {
                auto msg = messageQueue_.front();
                messageQueue_.pop();
                lock.unlock();

                for (auto& sim : sims_) {
                    std::unique_lock<std::mutex> simLock(sim->getMutex());
                    if (!sim->isBlocked()) {
                        sim->processMessage(msg);
                        break;
                    }
                }
            } else {
                lock.unlock();
                std::this_thread::yield();
            }
        }
    }
};

