['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h> // For memory pools
#include <sys/time.h> // For time measurements
#include <semaphore.h> // For thread-safe access

// External data store interface
typedef struct {
    void* handle;
    void (*store)(void*, const NFAPI_CRC_INDICATION_PDU_T*);
    NFAPI_CRC_INDICATION_PDU_T* (*retrieve)(void*);
} StoreInterface;

// Memory pool for NFAPI_CRC_INDICATION_PDU_T structures
typedef struct MemPool {
    size_t capacity;
    void* data;
} MemPool;

void init_mempool(MemPool*, size_t);
NFAPI_CRC_INDICATION_PDU_T* mempool_alloc(MemPool*);
void mempool_free(MemPool*, NFAPI_CRC_INDICATION_PDU_T*);

// Lock for thread-safe access to the memory pool
sem_t mempool_lock;

// Function prototype
void create_structures(StoreInterface*, size_t);

int main() {
    // Initialize and configure external data store, memory pool, etc.
    StoreInterface store_interface = { .handle = NULL };
    MemPool mempool = {};
    init_mempool(&mempool, 10000); // Allocate memory for 10,000 structures

    create_structures(&store_interface, 10000);

    return 0;
}

void create_structures(StoreInterface* store_if, size_t num_structures) {
    MemPool *mempool = &mempool; // Shorten the name for readability
    pthread_t threads[num_structures];
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    long64_t total_elapsed = 0;

    sem_init(&mempool_lock, 0, 1); // Initial value is not important here

    for (size_t i = 0; i < num_structures; ++i) {
        pthread_create(&threads[i], NULL, create_structure, (void*)store_if);
    }

    for (size_t i = 0; i < num_structures; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_gettime(CLOCK_MONOTONIC, &ts);
    total_elapsed += (ts.tv_sec - ts.tv_nsec / 1_000_000_000) * num_structures;
    printf("Total elapsed time: %.3f ms\n", total_elapsed / 1e3);
}

void* create_structure(void* store_if_ptr) {
    StoreInterface* store_if = (StoreInterface*)store_if_ptr;
    NFAPI_CRC_INDICATION_PDU_T* pdu = mempool_alloc(mempool);

    // Populate the structure with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG

    sem_t lock;
    sem_init(&lock, 0, 1); // Locks for thread-safe access to the memory pool

    // Acquire the lock before modifying the memory pool to ensure thread safety
    sem_wait(&mempool_lock);

    // Access the memory pool with the lock held
    // Modify the pdu, store it in the external data store and release the lock

    sem_post(&mempool_lock);

    return NULL;
}

void init_mempool(MemPool* mempool, size_t capacity) {
    memset(mempool, 0, sizeof(MemPool));
    mempool->capacity = capacity;
    void* data = mmap(NULL, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    mempool->data = data;
}

NFAPI_CRC_INDICATION_PDU_T* mempool_alloc(MemPool* mempool) {
    if (mempool->capacity == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(mempool->data);

    sem_t lock;
    sem_init(&lock, 0, 1); // Locks for thread-safe access to the memory pool

    sem_wait(&mempool_lock);

    size_t next_index = mempool->next_index % mempool->capacity;
    NFAPI_CRC_INDICATION_PDU_T* next_pdu = pdu + next_index;

    if (next_pdu->is_used) {
        // Reuse a previously freed structure
        sem_post(&mempool_lock);
        sem_wait(&lock);
        next_pdu->is_used = true;
        memset(next_pdu, 0, sizeof(*next_pdu));
        sem_post(&lock);
    } else {
        // Allocate a new structure
        sem_post(&mempool_lock);
        mempool->next_index++;
        memset(next_pdu, 0, sizeof(*next_pdu));
        next_pdu->is_used = true;
    }

    return next_pdu;
}

void mempool_free(MemPool* mempool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_t lock;
    sem_init(&lock, 0, 1); // Locks for thread-safe access to the memory pool

    sem_wait(&mempool_lock);

    size_t index = (static_cast<size_t>(pdu - mempool->data)) % mempool->capacity;
    NFAPI_CRC_INDICATION_PDU_T* next_pdu = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(mempool->data) + index;

    sem_post(&mempool_lock);
    sem_wait(&lock);
    pdu->is_used = false;
    sem_post(&lock);
}
```

