    if (!str.length()) return "";

    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str.c_str(), str.length());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        std::stringstream ss;
        ss << std::hex << static_cast<unsigned>(digest[i]);
        if (ss.str().length() == 1) result += '0'; // fill zeros when single digit
        result += ss.str();
    }

    return result;
}

