void selectAttack(int& attackNum, std::chrono::steady_clock::time_point& lastSelection) {
    static std::mt19937 generator; // random device used (Mersenne Twister 19937)
    static std::uniform_int_distribution<> distribution(0, 1); // uniform int distribution between 0 and 1

    if ((std::chrono::steady_clock::now() - lastSelection) >= std::chrono::seconds(9)) {
        lastSelection = std::chrono::steady_clock::now();
        attackNum = distribution(generator);
    }
}
