    byte[] resultHash;
    using (var stream = new MemoryStream()) {
        var writer = new StreamWriter(stream);
        writer.Write(str);
        writer.Flush();
        md5.TransformBlock(stream.ToArray(), 0, stream.Length, resultHash, 0);
        stream.Close();
    }
    return BitConverter.ToString(resultHash).Replace("-", "");
}
