    public WebFluxConfigurer<ServerCodecConfigurer> serverCodecConfigurer() {
        return new WebFluxConfigurer<>() {
            @Override
            public void configureCodecs(ServerCodecConfigurer configurer) {
                configurer.defaultCodecs().maxInboundLineLength(webServerProperties.getMaxLineLength());
            }
        };
    }

    HttpServerWebHandler httpHandler() {
        return new HttpServerWebHandler(ResourcePools.newBoundedPool(50, webServerProperties.getThreadLimits().maxProcessors()))
