2. OAuth2 access token validation:

```cpp
#include <nlohmann/json.hpp>
using json = nlohmann::json;

bool validateOauthToken(const std::string& token) {
    json j = json::parse(token);

    if(!j.contains("access_token") || !j["access_token"].is_string() ||
       !j.contains("expires_in") || !j["expires_in"].is_number() ||
       !j.contains("token_type") || j["token_type"] != "Bearer" ||
       j["expires_in"] <= 0) {
        return false;
    }

    // Optional refresh_token validation if required.

    return true;
}
