import org.apache.beam.sdk.Pipeline
import org.apache.beam.sdk.coders.AvroCoder
import org.apache.beam.sdk.io.gcp.bigquery.BigQueryIO
import org.apache.beam.sdk.options.PipelineOptionsFactory
import org.apache.beam.sdk.transforms.*
import org.apache.beam.sdk.values.KV
import org.slf4j.LoggerFactory

data class DataSchema(val field1: String, val field2: String)

class BatchDataProcessor {
    private val logger = LoggerFactory.getLogger(javaClass)

    fun run(options: RunOptions) {
        withStreamedData()
            .apply(ParDo<KV<String, Any>, KV<String, Any>>(ValidateData())).apply(ParDo<KV<String, Any>, KV<String, Any>>(TransformData()))
            .apply(BigQueryIO.write().to(options.bigqueryTable)
                .withCoder(AvroCoder.of(DataSchema::class.java))
                .withoutValidation())
            .run(PipelineOptionsFactory.create(options))
    }

    private fun withStreamedData(): Pipeline {
        val options = PipelineOptionsFactory.create()
        options.viewAs(TaskQueueOptions::class.java).setRunner(options.runner)
        options.setJobName("BatchDataProcessor")
        return Pipeline.create(options)
    }
}

