const books = {
    // Define your Old Testament books here as objects with 'name' and 'regex' properties
};

function findBooksOldTestament(text) {
    const wordRegex = /\b(?:[A-Z]{3,}\s?|\w+\s?[A-Z]\s?)*\b/g; // Matches whole words

    let booksFound = {};
    let match;
    while ((match = wordRegex.exec(text)) !== null) {
        for (let book in books) {
            if (books[book].regex.test(match[0])) {
                if (!booksFound.hasOwnProperty(book)) {
                    booksFound[book] = 0;
                }
                booksFound[book]++;
                break;
            }
        }
    }
    return booksFound;
}
