public class DataProcessingPipeline
{
    private readonly Dictionary<string, IDataProcessor> _processors = new Dictionary<string, IDataProcessor>();
    private readonly Dictionary<string, IOutputSink> _sinks = new Dictionary<string, IOutputSink>();

    public void RegisterDataSource(IDataSource dataSource)
    {
