    }

    public void RegisterOutputSink(IOutputSink outputSink)
    {
        // Validate and register the output sink
    }

    public async Task ProcessAsync()
    {
        var sources = _processors.Keys.ToList();

        foreach (var source in sources)
        {
            if (_processors[source].IsAvailable())
            {
                await _processors[source].PullDataAsync().ConfigureAwait(false);

                var sinks = GetSinksForSource(source);

                foreach (var sink in sinks)
                {
                    if (sink.IsAvailable())
                    {
                        await _sinks[sink].PushDataAsync(_processors[source].GetCurrentData()).ConfigureAwait(false);
                    }
                }
            }
        }
    }

    private IEnumerable<IOutputSink> GetSinksForSource(string source)
    {
        return _sinks.Where(x => x.Value.SupportsData(source));
    }
}
```

