JavaScript Function:

```javascript
const asyncReduce = (arr, callback, initialValue) => {
  return new Promise((resolve, reject) => {
    let result = initialValue;
    let index = 0;

    const processNext = () => {
      if (index >= arr.length) {
        return resolve(result);
      }

      callback(result, arr[index], (err, nextResult) => {
        if (err) {
          return reject(err);
        }

        result = nextResult;
        index++;
        processNext();
      });
    };

    processNext();
  });
};
```

