2. C Function for loading resource bundle:

```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int load_resource_bundle(const char *filename, void **bundle) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        return errno;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    rewind(file);

    void *data = malloc(size);
    if (!data) {
        fclose(file);
        return errno;
    }

    size_t read = fread(data, 1, size, file);
    if (read != size) {
        free(data);
        fclose(file);
        return errno;
    }

    fclose(file);
    *bundle = data;
    return 0;
}
```

