using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;

public async Task<string> LoadResourceBundle(string directoryPath)
{
    var filePaths = Directory.EnumerateFiles(directoryPath, "*.json");

    if (!filePaths.Any())
        throw new FileNotFoundException($"No files found in the specified path: {directoryPath}.");

    var itemsMetadataList = new List<ItemMetadata>();

    var tasks = filePaths.Select(async filePath =>
    {
        try
        {
            using (var reader = new StreamReader(filePath))
            using (var jsonReader = new JsonTextReader(reader))
            {
                var serializer = new JsonSerializer();
                var item = serializer.Deserialize<Item>(jsonReader);

                itemsMetadataList.Add(item.ToMetadata());
            }
        }
        catch (Exception ex)
        {
            return (ex.Message, null);
        }

        return (null, item);
    });

    var results = await Task.WhenAll(tasks);

    var failedItems = results.Where(t => t.Item1 != null).ToList();
    foreach (var (errorMessage, _) in failedItems)
        Console.WriteLine($"Error occurred while loading item: {errorMessage}");

    var successfulItems = results.Where(t => t.Item2 != null).Select(t => t.Item2).ToList();

    return JsonConvert.SerializeObject(successfulItems, Formatting.Indented);
}
```

This implementation reads JSON files from a specified directory and deserializes them using Newtonsoft.Json library. It supports concurrent access by running each file load task asynchronously using Task.WhenAll. If there are any errors during the loading process, it logs the error message and continues with other tasks. The function returns the serialized metadata of successfully loaded items as a JSON string.

You should implement the remaining components according to your project's specific requirements and best practices for performance optimization, resource management, error handling, maintainability, security, and extensibility.']

