<?php
namespace App\Security;

use Argon2\Argon2i;
use Passlib\Hash\BcryptHash;
use PhpSecLib3\PasswordStrength\QuickCheck as StrengthChecker;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class SecurityUtil
{
    protected $passwordHasher;
    protected $logger;
    protected $apiClient;

    public function __construct(BcryptHash $bcrypt, Logger $logger, ApiClient $apiClient)
    {
        $this->passwordHasher = $bcrypt;
        $this->logger = $logger;
        $this->apiClient = $apiClient;
    }

    public function generateRandomString($length = 32, $charset = null): string
    {
        if (!is_null($charset) && !is_array($charset)) {
            throw new \InvalidArgumentException('Charset must be an array.');
        }

        if (is_null($charset)) {
            $charset = range(0, 9) + range('a', 'z') + range('A', 'Z');
        }

        $strengthChecker = new StrengthChecker();
        while (!$strengthChecker->check($randomString = implode('', array_map("mt_rand", $charset))) || strlen($randomString) < $length) {
            $randomString = implode('', array_map("mt_rand", $charset));
        }

        return $randomString;
    }

    public function hashPassword($password, $options = []): string
    {
        if (!array_key_exists('timeCostFactor', $options) || !is_int($options['timeCostFactor']) || $options['timeCostFactor'] <= 2) {
            $options['timeCostFactor'] = 10;
        }
        if (!array_key_exists('memoryCostFactor', $options) || !is_int($options['memoryCostFactor']) || $options['memoryCostFactor'] <= 2) {
            $options['memoryCostFactor'] = 16;
        }
        if (!array_key_exists('parallelism', $options) || !is_int($options['parallelism']) || $options['parallelism'] <= 1) {
            $options['parallelism'] = 2;
        }

        try {
            return $this->passwordHasher->hash($password, PASSLIB_HASH_ARGON2I, $options);
        } catch (\Exception $e) {
            throw new \RuntimeException("Failed to hash password: {$e->getMessage()}");
        }
    }

    public function verifyPassword($storedHash, $providedPassword): bool
    {
        try {
            return $this->passwordHasher->verify($providedPassword, $storedHash);
        } catch (\Exception $e) {
            $this->logger->warning("Failed to verify password: {$e->getMessage()}");
            return false;
        }
    }

    public function logFailedLoginAttempt()
    {
        $this->logger->error('Failed login attempt');
    }

    // Additional methods for integrating with external API, auto-rotating security secrets, and other specified functionalities go here.
}
```

