I will use a `pthread_mutex_t` to ensure thread safety and an adaptive array (using doubling technique) for efficient memory allocation and minimization of fragmentation.

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} ThreadSafeArray;

ThreadSafeArray* threadSafeArrayNew(size_t initialSize) {
    ThreadSafeArray* arr = (ThreadSafeArray*) malloc(sizeof(ThreadSafeArray));
    if (!arr) return NULL;
    arr->data = (NFAPI_CRC_INDICATION_PDU_T*) calloc(initialSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    arr->capacity = initialSize;
    arr->length = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void threadSafeArrayLock(ThreadSafeArray* array) {
    pthread_mutex_lock(&array->lock);
}

void threadSafeArrayUnlock(ThreadSafeArray* array) {
    pthread_mutex_unlock(&array->lock);
}

NFAPI_CRC_INDICATION_PDU_T* threadSafeArrayGet(ThreadSafeArray* array, size_t index) {
    threadSafeArrayLock(array);
    NFAPI_CRC_INDICATION_PDU_T* data = &array->data[index];
    threadSafeArrayUnlock(array);
    return data;
}

void threadSafeArraySet(ThreadSafeArray* array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    threadSafeArrayLock(array);
    array->data[index] = *pdu;
    threadSafeArrayUnlock(array);
}

