1. Create an `EncryptionService` class:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Google.Apis.Auth.AspNetCore;

public class EncryptionService
{
    private readonly KeyVaultClient keyVaultClient;
    private readonly SymmetricKeyAlgorithmProvider keyAlgorithm;

    public EncryptionService(IConfiguration configuration)
    {
        var keyVaultConfig = configuration.GetSection("KeyVault");
        keyVaultClient = new KeyVaultClient(new KeyVaultClient.AuthenticationCallback(AsyncGoogleAuthProvider.CreateDefaultWebAuthorization));
        keyVaultClient.SetLeaseDuration(new TimeSpan(0, 2, 0)); // Set appropriate lease duration
        keyAlgorithm = AES.Create();
    }

    public async Task<EncryptResponse> EncryptAsync(EncryptRequest request)
    {
        var key = await GetKeyAsync(request.KeyId);
        var iv = new byte[12]; // Generate a random IV for each encryption operation
        using (var aes = keyAlgorithm.CreateEncryptor(key, iv))
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, aes, CryptoStreamMode.Write))
                {
                    await cs.WriteAsync(request.Data, 0, request.Data.Length);
                    cs.FlushFinalBlock();
                }

                return new EncryptResponse(iv, Convert.ToBase64String(ms.ToArray()));
            }
        }
    }

    public async Task<DecryptResponse> DecryptAsync(DecryptRequest request)
    {
        var key = await GetKeyAsync(request.KeyId);
        using (var aes = keyAlgorithm.CreateDecryptor(key, request.Iv))
        {
            var data = Convert.FromBase64String(request.CipherText);
            using (var ms = new MemoryStream(data))
            {
                using (var cs = new CryptoStream(ms, aes, CryptoStreamMode.Read))
                {
                    var result = new byte[cs.ReadByte()];
                    await cs.ReadAsync(result, 0, result.Length);
                    return new DecryptResponse(Encoding.UTF8.GetString(result));
                }
            }
        }
    }

    private async Task<byte[]> GetKeyAsync(string keyId)
    {
        var secret = await keyVaultClient.GetSecretAsync(keyId);
        return Convert.FromBase64String(secret.Value);
    }
}
```

