    {
        var cmd = new SqlCommand(commandText);
        foreach (var parameter in parameters)
        {
            if (parameter is DBNull dbNull)
            {
                cmd.Parameters.Add(new SqlParameter(cmd.Parameters.Count + 1).WithValue(dbNull));
            }
            else
            {
                cmd.Parameters.Add(new SqlParameter(cmd.Parameters.Count + 1, parameter));
            }
