    pthread_exit(nullptr);
}

int process_command(const std::string& xml_data, const char* xpath_expr) {
    CommandData cmd_data;
    cmd_data.xml_data = xml_data;
    cmd_data.xpath_expr = xpath_expr;

    pthread_t thread_id;
