```java
import java.time.Duration;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class JavaServiceManager {
    private static final Random RANDOM = new Random();
    private ExecutorService executor = Executors.newSingleThreadExecutor();
    private Queue<Runnable> serviceTasks = new LinkedBlockingQueue<>();
    private MonitoringSystem monitoringSystem;

    public JavaServiceManager(MonitoringSystem monitoringSystem) {
        this.monitoringSystem = monitoringSystem;
    }

    public void start() {
        executor.submit(() -> runServices());
    }

    public void stop() {
        executor.shutdown();
    }

    private void runServices() {
        while (!executor.isTerminated()) {
            Runnable task = serviceTasks.poll(Duration.ofMillis(RANDOM.nextInt(100) + 500), TimeUnit.MILLISECONDS);
            if (task != null) {
                try {
                    task.run();
                } catch (Exception e) {
                    System.err.println("Error while running service: " + e.getMessage());
                } finally {
                    // Report the state of the service to monitoring system
                    monitoringSystem.reportState(task.toString());
                }
            }
        }
    }

    public void addServiceTask(Runnable task) {
        serviceTasks.add(task);
    }
}
```']

