class CircuitBreaker:
    def __init__(self, max_retries, initial_backoff, multiplier, jitter):
        self.max_retries = max_retries
        self.initial_backoff = initial_backoff
        self.multiplier = multiplier
        self.jitter = jitter
        self.state = 'closed'
        self.last_failure = 0

    def call(self, fn):
        def wrapped(*args, **kwargs):
            if self.state == 'open':
                wait_until_open()
            response = fn(*args, **kwargs)
            if not response or response.status_code >= 500:
                self.mark_failure()
                raise Exception('API call failed')
            return response
        return wrapped

    def mark_failure(self):
        current_time = int(time.time())
        if (current_time - self.last_failure) < (self.initial_backoff * (2 ** self.attempt)):
            time.sleep((self.initial_backoff * (2 ** self.attempt)) + random.uniform(*self.jitter))
        else:
            self.reset()
        self.state = 'open'

    def reset(self):
        self.attempt = 0
        self.state = 'half-open'
        self.last_failure = int(time.time())

    def is_open(self):
        return self.state == 'open'

def wait_until_open():
    remaining_time = self.recovery_time - (int(time.time()) % self.recovery_time)
    if remaining_time > 0:
        time.sleep(remaining_time)

