    public String computeHash(String filePath) throws IOException, ExecutionException, InterruptedException {
        File file = new File(filePath);
        if (!file.exists() || !file.isFile()) {
            throw new FileNotFoundException();
        }

        long fileSize = file.length();
        if (fileSize > MAX_FILE_SIZE) {
            // Integrate with external API for hashing large files
            RequestBody requestBody = RequestBody.create(MediaType.get("application/octet-stream"), FileUtils.readFileToByteArray(file));
            HttpUrl url = HttpUrl.parse(apiEndpoint).newBuilder()
                    .addQueryParameter("token", generateToken())
                    .build();
            Request request = new Request.Builder()
                    .url(url)
                    .post(requestBody)
                    .build();
            Call call = httpClient.newCall(request);
            Future<Response> future = executor.submit(() -> call.execute());
            Response response = future.get(1, TimeUnit.SECONDS);
            if (!response.isSuccessful()) {
                throw new IOException("Failed to get hash from API");
            }
            return response.header("X-Hashed-Hash"); // Assuming API returns hash in "X-Hashed-Hash" header
