1. **C-based core engine:** Use data structures like linked lists or hash tables to handle dynamic resizing. Implement memory-efficient compression algorithms (e.g., zlib) to minimize overhead during log ingestion. For detecting redundant entries, use a CRC32 checksum or other hash functions to compare log entries.

```c++
#include <zlib/zlib.h>
#include <hash_map>

struct LogEntry {
    // Properties for log entry
};

class RedundantCheckSum {
private:
    uLong checksum;
public:
    RedundantCheckSum() : checksum(0) {}
    void update(const LogEntry& entry) {
        uChar buffer[sizeof(LogEntry)];
        memcpy(buffer, &entry, sizeof(LogEntry));
        inflateEnd(&infl, NULL);
        inflateReset(&infl);
        infl.next_in = (Bytef*)buffer;
        infl.avail_in = sizeof(LogEntry);
        infl.next_out = (Bytef*)(&checksum);
        infl.avail_out = sizeof(checksum);
        inflate(&infl, Z_SYNC_FLUSH);
    }
};
```

